// pxl-kernel/setting/schema.spec.rs
//
// GENERATED by pxl-tool/bin/spec.rs from schema.json — do not edit.
//
// Every setting the app has, declared once: its default, its kind, and
// where the settings sheet shows it. The store reads the defaults from here
// and the sheet renders rows from here, so adding a setting is one entry in
// SETTINGS plus its two strings in the locale catalog under
// `settings.<section>.<key>`. A choice may carry `costs` beside its
// `options`, one per option in the same order, for when what an option costs
// differs from its neighbors'; an empty string is no badge. A `dev` setting
// is in the kernel's table in every build and offered only under a
// development one; the shell's production bundle carries SETTINGS_SHIPPED,
// the table without them, in SETTINGS' place.
//
// A choice's `options` names one of the lists below, and the option crosses
// and is held as its index there; only storage keeps it by name. A setting
// is numbered by its place in SETTINGS (the kernel's SettingKey), which is
// what crosses for it. An `index` is a place in a list kept elsewhere — the
// person and the pet are by theirs in variant.json — and crosses as itself.

// Casing here is the spec's and not Rust's: a name is spelled as the JSON
// spells it, so that one record is indexed by one name on both sides. To
// case them the way Rust would is to rename the protocol.
#![allow(non_camel_case_types)]

/// Which controller makes the camera's pose.
///
///   orbit — third person: the camera turns about the focus, its
///           radius ahead of the eye, and a drag moves the focus.
///   free  — first person: the eye is the focus and turns in place;
///           a drag walks it as the orbit's center walks, the eye at its
///           height over where the walk stands.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum CameraMode {
    orbit = 0,
    free = 1,
}

impl CameraMode {
    pub const ALL: [CameraMode; 2] = [CameraMode::orbit, CameraMode::free];

    /// The option an index names, or none for an index past the list.
    pub fn of(index: u32) -> Option<CameraMode> {
        CameraMode::ALL.get(index as usize).copied()
    }
}

/// What terrain does to the camera.
///
///   through — nothing. The eye goes wherever the controls put it, ground
///             included, where the terrain shell has no inward-facing
///             geometry and the scene reads inside out.
///   stop    — a control goes as far as it asked or as far as it can.
///             Nothing moves on its own; a zoom into a hill stops short.
///   climb   — dist is always granted and the *view* pitches up instead,
///             as far as straight down, so every zoom stays
///             reachable at the cost of an angle nobody asked for.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum OrbitObstacleMode {
    through = 0,
    stop = 1,
    climb = 2,
}

impl OrbitObstacleMode {
    pub const ALL: [OrbitObstacleMode; 3] = [OrbitObstacleMode::through, OrbitObstacleMode::stop, OrbitObstacleMode::climb];

    /// The option an index names, or none for an index past the list.
    pub fn of(index: u32) -> Option<OrbitObstacleMode> {
        OrbitObstacleMode::ALL.get(index as usize).copied()
    }
}

/// Where the ambient occlusion comes from.
///
///   off    — none.
///   corner — the screen pass's own: the floor along a cube and the inside
///            of a corner, where a neighbouring pixel's face rises in front
///            of the pixel's own plane within a block or two of it
///            (crates/client/render/src/frame/shader/screen_rays.wgsl).
///            A few taps of the rays a pixel, behind a uniform.
///   screen — N8AO
///            (crates/client/render/src/gpu/ao.rs): the world's depth drawn
///            once more, the occlusion sampled from it at half resolution,
///            denoised, and applied to every lit surface as a warm dark
///            tint. Five passes and 11 bytes a pixel.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum AoMode {
    off = 0,
    corner = 1,
    screen = 2,
}

impl AoMode {
    pub const ALL: [AoMode; 3] = [AoMode::off, AoMode::corner, AoMode::screen];

    /// The option an index names, or none for an index past the list.
    pub fn of(index: u32) -> Option<AoMode> {
        AoMode::ALL.get(index as usize).copied()
    }
}

/// How many device pixels the world is drawn at to a CSS pixel.
///
///   auto  — the display's, stepped down to a share of it while moving
///           frames run over their budget — the display's interval, no
///           tighter than a sixtieth of a second — and back up once they
///           have room (crates/client/kernel/src/view/frame/resolution.rs).
///   fixed — the display's, whatever the frames cost.
///   low   — one.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum ResolutionMode {
    auto = 0,
    fixed = 1,
    low = 2,
}

impl ResolutionMode {
    pub const ALL: [ResolutionMode; 3] = [ResolutionMode::auto, ResolutionMode::fixed, ResolutionMode::low];

    /// The option an index names, or none for an index past the list.
    pub fn of(index: u32) -> Option<ResolutionMode> {
        ResolutionMode::ALL.get(index as usize).copied()
    }
}

/// How a setting is held.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SettingKind {
    Toggle,
    Choice,
    Index,
}

/// Every setting, by its place in schema.json's SETTINGS.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum SettingKey {
    /// Ground color from the art pack (four taps of the layer array per
    /// fragment) instead of the flat per-instance average. The paint shader's
    /// `frame.low_spec` is this, inverted.
    ///
    /// Low because the four taps are all of it: fill rate, which scales with
    /// the screen and not with the world, and nothing else — no geometry, no
    /// pass of its own, and no work off the GPU past an atlas the client
    /// already holds.
    textures = 0,
    /// Procedurally scattered decor only; what the player placed stays.
    ///
    /// Med because it is models rather than a shading term: a cube of the eye's builds its
    /// decor and the frame draws it, so what it costs follows what is in view.
    /// It has been the frame's own bottleneck — 20260912-what-to-render-when.md
    /// reads GPU p95 24.1 ms with 2.26 M decor triangles and 15% of moving
    /// frames missing a vsync — and the projected-size criterion holds it to
    /// the nearest tier without making far decor cheap, the impostor tier that
    /// would being decided and not built. The badge is an ordering, and this is
    /// the one to reach for before any shading term.
    decor = 1,
    /// The cumulus' models and the altocumulus and cirrus sheets
    /// (crates/client/kernel/src/scene/environment/cloud.rs, crates/client/render/src/gpu/clouds.rs).
    /// Med as decor is: models in view, and a pass over the screen for the sheets.
    clouds = 2,
    /// The places' badges over the world, from the published places tiles.
    place = 3,
    /// Rotate-drag and pinch stop writing polar; azimuth is unaffected.
    /// Off by default: the tilt is the one control a view from above is expected to
    /// have, and locking it reads as the app being stuck.
    tilt_lock = 4,
    /// Which controller makes the camera's pose; CAMERA_MODES says each. To
    /// first person the person stands at the focus, the eye at its
    /// height over the ground; to third the focus is laid on the ground
    /// and the eye steps back by the radius.
    camera_mode = 5,
    /// The focus stands on what supports it and a pan takes the lowest way over what is in it (navigation/support.rs). Off, a pan keeps the center's height and passes through anything; a tap still stands it on the surface it struck.
    surface_follow = 6,
    /// What the camera does when the controls would put it underground; ORBIT_OBSTACLE_MODES says each.
    orbit_obstacle = 7,
    /// Darkens cube edges that border open air (crates/client/render/src/frame/shader/paint.wgsl).
    /// A few fragment ops behind a uniform; the shader is the same either way.
    edge_shade = 8,
    /// A uniform on an already-compiled shader term; not a pass.
    rim_light = 9,
    /// corner, the occlusion a voxel world reads off its own cubes' faces;
    /// screen, N8AO's screen-space pass, the costliest of the three. AO_MODES
    /// says each.
    ao = 10,
    /// The sun's shadow map (crates/client/render/src/gpu/shadow.rs): the world
    /// cast once more from the sun, a ray a texel through the world's query at
    /// the zooms the eye's rays ask (pxl-shader `sun_cs`), decor and the
    /// actors drawn into it depth only, and a 3x3 compare per fragment; 16 MB
    /// of map.
    shadows = 11,
    /// The pixels the world is filled at, the GPU's largest cost: two to a
    /// CSS pixel is four times the fragments of one. RESOLUTION_MODES says each.
    resolution = 12,
    /// Where the camera and the pointer are, read live (profiler/summary.rs, its view section).
    view = 13,
    /// The profiler's panel, with the profiler recording while it is on (profiler/window.rs `profiler_follow`).
    profiler = 14,
    /// Marks for the focus and the cell it floors to, and rings in the level, the view's upright and the north–south planes (scene/indicator/frame_gizmo.rs); and over the ground the eye's windows' squares by how they stand, their tiles and shards (scene/indicator/coverage_gizmo.rs).
    world_gizmo = 15,
    /// The camera grid over the screen, rings a cell apart about the optical axis cut into cells of one solid angle each, and the blocks the rays stop on tinted by the share of a grid cell a face shows the eye: green within one to four, blue finer, red coarser (scene/indicator/camera_gizmo.rs).
    camera_gizmo = 16,
    person = 17,
    pet = 18,
    /// Each ray's pixel coloured by the nodes its own walk asked the world from its cell's start, as the frame casts it, on one fixed log ramp up to 1024; grey where it showed a sample's block and walked nothing (crates/client/render/src/frame/shader/screen_rays.wgsl).
    ray_steps = 19,
}

impl SettingKey {
    pub const ALL: [SettingKey; 20] = [
        SettingKey::textures,
        SettingKey::decor,
        SettingKey::clouds,
        SettingKey::place,
        SettingKey::tilt_lock,
        SettingKey::camera_mode,
        SettingKey::surface_follow,
        SettingKey::orbit_obstacle,
        SettingKey::edge_shade,
        SettingKey::rim_light,
        SettingKey::ao,
        SettingKey::shadows,
        SettingKey::resolution,
        SettingKey::view,
        SettingKey::profiler,
        SettingKey::world_gizmo,
        SettingKey::camera_gizmo,
        SettingKey::person,
        SettingKey::pet,
        SettingKey::ray_steps,
    ];

    /// The setting a number names, or none for a number past the table.
    pub fn of(number: u32) -> Option<SettingKey> {
        SettingKey::ALL.get(number as usize).copied()
    }

    pub fn kind(self) -> SettingKind {
        match self {
            SettingKey::textures => SettingKind::Toggle,
            SettingKey::decor => SettingKind::Toggle,
            SettingKey::clouds => SettingKind::Toggle,
            SettingKey::place => SettingKind::Toggle,
            SettingKey::tilt_lock => SettingKind::Toggle,
            SettingKey::camera_mode => SettingKind::Choice,
            SettingKey::surface_follow => SettingKind::Toggle,
            SettingKey::orbit_obstacle => SettingKind::Choice,
            SettingKey::edge_shade => SettingKind::Toggle,
            SettingKey::rim_light => SettingKind::Toggle,
            SettingKey::ao => SettingKind::Choice,
            SettingKey::shadows => SettingKind::Toggle,
            SettingKey::resolution => SettingKind::Choice,
            SettingKey::view => SettingKind::Toggle,
            SettingKey::profiler => SettingKind::Toggle,
            SettingKey::world_gizmo => SettingKind::Toggle,
            SettingKey::camera_gizmo => SettingKind::Toggle,
            SettingKey::person => SettingKind::Index,
            SettingKey::pet => SettingKind::Index,
            SettingKey::ray_steps => SettingKind::Toggle,
        }
    }

    /// Its name, as storage keeps it.
    pub fn name(self) -> &'static str {
        match self {
            SettingKey::textures => "textures",
            SettingKey::decor => "decor",
            SettingKey::clouds => "clouds",
            SettingKey::place => "place",
            SettingKey::tilt_lock => "tilt_lock",
            SettingKey::camera_mode => "camera_mode",
            SettingKey::surface_follow => "surface_follow",
            SettingKey::orbit_obstacle => "orbit_obstacle",
            SettingKey::edge_shade => "edge_shade",
            SettingKey::rim_light => "rim_light",
            SettingKey::ao => "ao",
            SettingKey::shadows => "shadows",
            SettingKey::resolution => "resolution",
            SettingKey::view => "view",
            SettingKey::profiler => "profiler",
            SettingKey::world_gizmo => "world_gizmo",
            SettingKey::camera_gizmo => "camera_gizmo",
            SettingKey::person => "person",
            SettingKey::pet => "pet",
            SettingKey::ray_steps => "ray_steps",
        }
    }

    /// A choice's options by name, in index order; none for any other kind.
    pub fn options(self) -> &'static [&'static str] {
        match self {
            SettingKey::camera_mode => &["orbit", "free"],
            SettingKey::orbit_obstacle => &["through", "stop", "climb"],
            SettingKey::ao => &["off", "corner", "screen"],
            SettingKey::resolution => &["auto", "fixed", "low"],
            _ => &[],
        }
    }

    /// Offered by a development build only.
    pub fn dev(self) -> bool {
        matches!(self, SettingKey::surface_follow | SettingKey::ray_steps)
    }

    /// A choice's option a development build only offers.
    pub fn dev_option(self, value: u32) -> bool {
        match self {
            SettingKey::orbit_obstacle => matches!(value, 0),
            _ => false,
        }
    }
}

/// Every setting's value: what the store holds, and what the app reads.
#[derive(Clone, Debug, PartialEq)]
pub struct Settings {
    pub textures: bool,
    pub decor: bool,
    pub clouds: bool,
    pub place: bool,
    pub tilt_lock: bool,
    pub camera_mode: CameraMode,
    pub surface_follow: bool,
    pub orbit_obstacle: OrbitObstacleMode,
    pub edge_shade: bool,
    pub rim_light: bool,
    pub ao: AoMode,
    pub shadows: bool,
    pub resolution: ResolutionMode,
    pub view: bool,
    pub profiler: bool,
    pub world_gizmo: bool,
    pub camera_gizmo: bool,
    pub person: u8,
    pub pet: u8,
    pub ray_steps: bool,
}

impl Settings {
    /// Every setting at schema.json's default.
    pub const DEFAULT: Settings = Settings {
        textures: true,
        decor: true,
        clouds: true,
        place: false,
        tilt_lock: false,
        camera_mode: CameraMode::orbit,
        surface_follow: true,
        orbit_obstacle: OrbitObstacleMode::climb,
        edge_shade: true,
        rim_light: true,
        ao: AoMode::corner,
        shadows: false,
        resolution: ResolutionMode::auto,
        view: false,
        profiler: false,
        world_gizmo: false,
        camera_gizmo: false,
        person: 1,
        pet: 5,
        ray_steps: false,
    };

    /// A setting's value as it crosses: a toggle's 0 or 1, a choice's option
    /// by its place in its list, an index as itself.
    pub fn get(&self, key: SettingKey) -> u32 {
        match key {
            SettingKey::textures => self.textures as u32,
            SettingKey::decor => self.decor as u32,
            SettingKey::clouds => self.clouds as u32,
            SettingKey::place => self.place as u32,
            SettingKey::tilt_lock => self.tilt_lock as u32,
            SettingKey::camera_mode => self.camera_mode as u32,
            SettingKey::surface_follow => self.surface_follow as u32,
            SettingKey::orbit_obstacle => self.orbit_obstacle as u32,
            SettingKey::edge_shade => self.edge_shade as u32,
            SettingKey::rim_light => self.rim_light as u32,
            SettingKey::ao => self.ao as u32,
            SettingKey::shadows => self.shadows as u32,
            SettingKey::resolution => self.resolution as u32,
            SettingKey::view => self.view as u32,
            SettingKey::profiler => self.profiler as u32,
            SettingKey::world_gizmo => self.world_gizmo as u32,
            SettingKey::camera_gizmo => self.camera_gizmo as u32,
            SettingKey::person => self.person as u32,
            SettingKey::pet => self.pet as u32,
            SettingKey::ray_steps => self.ray_steps as u32,
        }
    }

    /// Sets a setting from its value as it crosses; false, and nothing set,
    /// for a value the setting cannot hold.
    pub fn set(&mut self, key: SettingKey, value: u32) -> bool {
        match key {
            SettingKey::textures if value <= 1 => self.textures = value == 1,
            SettingKey::decor if value <= 1 => self.decor = value == 1,
            SettingKey::clouds if value <= 1 => self.clouds = value == 1,
            SettingKey::place if value <= 1 => self.place = value == 1,
            SettingKey::tilt_lock if value <= 1 => self.tilt_lock = value == 1,
            SettingKey::camera_mode => match CameraMode::of(value) {
                Some(o) => self.camera_mode = o,
                None => return false,
            },
            SettingKey::surface_follow if value <= 1 => self.surface_follow = value == 1,
            SettingKey::orbit_obstacle => match OrbitObstacleMode::of(value) {
                Some(o) => self.orbit_obstacle = o,
                None => return false,
            },
            SettingKey::edge_shade if value <= 1 => self.edge_shade = value == 1,
            SettingKey::rim_light if value <= 1 => self.rim_light = value == 1,
            SettingKey::ao => match AoMode::of(value) {
                Some(o) => self.ao = o,
                None => return false,
            },
            SettingKey::shadows if value <= 1 => self.shadows = value == 1,
            SettingKey::resolution => match ResolutionMode::of(value) {
                Some(o) => self.resolution = o,
                None => return false,
            },
            SettingKey::view if value <= 1 => self.view = value == 1,
            SettingKey::profiler if value <= 1 => self.profiler = value == 1,
            SettingKey::world_gizmo if value <= 1 => self.world_gizmo = value == 1,
            SettingKey::camera_gizmo if value <= 1 => self.camera_gizmo = value == 1,
            SettingKey::person => match u8::try_from(value) {
                Ok(n) => self.person = n,
                Err(_) => return false,
            },
            SettingKey::pet => match u8::try_from(value) {
                Ok(n) => self.pet = n,
                Err(_) => return false,
            },
            SettingKey::ray_steps if value <= 1 => self.ray_steps = value == 1,
            _ => return false,
        }
        true
    }
}
